package com.jobsphere.repository;
import com.jobsphere.entity.CourseCertificate; import org.springframework.data.jpa.repository.JpaRepository; import java.util.List; import java.util.Optional;
public interface CourseCertificateRepository extends JpaRepository<CourseCertificate,Long>{ List<CourseCertificate> findByUserIdOrderByIssuedAtDesc(Long userId); Optional<CourseCertificate> findByAttemptId(Long attemptId); }